mapper.update:
UPDATE consignment_unpost
SET is_settled  = true,
    cbr_id      = #{cbrId},
    updated_at  = CURRENT_TIMESTAMP
WHERE is_settled = false
  AND store      = #{store}
  AND sales_date >= #{fromDate}
  AND sales_date <= #{toDate}

mapper.select:
SELECT COUNT(id)
FROM customer_billing_request
WHERE store     = #{store}
  AND from_date = #{fromDate}
  AND to_date   = #{toDate}
  AND status IN ('HELD', 'RELEASED')
